use std::cell::Cell;

thread_local! {
    pub static DROP_COUNT: Cell<i32> = Cell::new(0);
}

pub struct Resource {
    pub id: i32,
}

impl Drop for Resource {
    fn drop(&mut self) {
        DROP_COUNT.with(|c| c.set(c.get() + 1));
    }
}

fn main() {
    let _r = Resource { id: 1 };
}
